S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# all L tetromino? actually triomino L = 3 cell 2x2 missing one
for sq in [ {(r,c) for r in range(2) for c in range(2,4)}, {(r,c) for r in range(2) for c in range(1,3)}, {(r,c) for r in range(2) for c in range(4,6)} ]:
 if not sq<=S: continue
 R=S-sq
 shapes=[]
 for r in range(4):
  for c in range(5):
   box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
   for miss in box:
    sh=box-{miss}
    if sh<=R: shapes.append(sh)
 def rec(rem, chosen):
  if not rem: return chosen
  p=min(rem)
  for sh in shapes:
   if p in sh and sh<=rem:
    x=rec(rem-sh,chosen+[sh])
    if x:return x
 print('square',sq, 'cover',rec(R,[]))
